    [8417] = {n="Un espíritu afligido", d="Habla con el Héroe Caído de la Horda en la entrada de Las Tierras Devastadas."},
    [8420] = {n="Caliente y picante", d="Lleva un retal de tela de inferi a Diblis a Frondavil.", tgo={{"Manáfago", "Avizor guardia vil", "Sátiro Legashi"}}},
