    [8424] = {n="La guerra contra los Sombra Jurada", d="Acaba con los Sombra Jurada en las Tierras Devastadas y regresa junto al Héroe Caído de la Horda.", tgo={{"Adepto Sombra Jurada"}, {"Cultor Sombra Jurada"}, {"Matón Sombra Jurada"}}},
    [8425] = {n="Plumas Vudú", d="Llévale las plumas vudú de los trols del Templo Sumergido al Héroe Caído de la Horda.", tgo={{"Gasher", "Zul'Lor", "Gasher"}, {"Hukku", "Mijan", "Hukku"}, {"Zolo", "Loh'ro", "Loh'ro"}}, star={"Frasco de diamante", {"WARRIOR"}}},
    [8460] = {n="Aliado a los Fauces de Madera", d="Grazle quiere que demuestres tu valía matando a 6 guerreros Muertobosque, 6 abrecaminos Muertobosque y 6 jardineros Muertobosque. Cuando lo hayas hecho, vuelve con él al sur de Frondavil, cerca del Santuario Esmeralda.", tgo={{"Guerrero Muertobosque"}, {"Abrecaminos Muertobosque"}, {"Jardinero Muertobosque"}}},
    [8461] = {n="Los Muertobosque del Norte", d="Nafien quiere que mates a 6 vigilantes del cubil Muertobosque, 6 vengadores Muertobosque y 6 chamanes Muertobosque. Luego, vuelve a buscarlo al norte de Frondavil, cerca de la entrada del Bastión de los Fauces de Madera.", tgo={{"Vigía del cubil Muertobosque"}, {"Vengador Muertobosque"}, {"Chamán Muertobosque"}}},
    [8462] = {n="Habla con Nafien", d="Viaja hacia el norte por el camino principal de Frondavil y habla con el fúrbolg Nafien. Está haciendo guardia en la entrada del Bastión de los Fauces de Madera."},
    [8464] = {n="Actividad de los Nevada", d="Salfa quiere que mates 8 chamanes Nevada, 8 Vigilantes del cubil Nevada y 8 ursas Nevada. Salfa está a las puertas del Bastión de los Fauces de Madera en Cuna del Invierno.", tgo={{"Chamán Nevada"}, {"Vigilante del cubil Nevada"}, {"Ursa Nevada"}}},
    [8465] = {n="Habla con Salfa", d="Viaja por el Bastión de los Fauces de Madera y sal a Cuna del Invierno. Habla con Salfa, que está haciendo guardia en la entrada del Bastión de los Fauces de Madera."},
    [8551] = {n="El cofre del capitán", d="Lleva el cofre de Smotts a Hecklebury Smotts en la Bahía del Botín.", tgo={{"Gorlash"}}},
    [9051] = {n="Prueba de toxicidad", d="Clávale la púa de devilsaurio a un devilsaurio. Ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro cuando hayas completado tu tarea."},
    [9052] = {n="Veneno de pétalo de sangre", d="Reúne 8 champiñones de sangre y 8 aguijones Gorishi, y ve a ver de nuevo a Torwa Abrecaminos al Cráter de Un'Goro.", tgo={{"Avispa Gorishi", "Aguijonero Gorishi"}, {}}, objs={"Brote pétalo de sangre"}},
    [9053] = {n="Un ingrediente mejor", d="Consigue una vid pútrida de las que custodia el guardián en las profundidades del Templo Sumergido y después ve a ver de nuevo a Torwa Abrecaminos.", tgo={{"Atal'alarion"}}, star={"Pelambre canoso", {"DRUID"}}},
    [65593] = {n="Los corazones de los amantes", d="Llévale los corazones de Avelina Lilly e Isaac Pearson a Carendin Halgar, que está en el Templo de los Condenados.", tgo={{"Avelina Lilly"}, {"Isaac Pearson"}}},
    [65597] = {n="El vínculo", d="Utilizando los corazones de los amantes, invoca y domina a un íncubo, y después devuélvele los corazones de amantes a Carendin Halgar, que está en el Barrio de la Magia de Entrañas.", tgo={{"Íncubo invocado"}}},
    [65601] = {n="El amor duele", d="Habla con Magar en Orgrimmar."},
    [65604] = {n="El vínculo", d="Usa el pañuelo deshilachado para invocar y dominar a un íncubo y después lleva el pañuelo a Gan'rul Ojosangre en Orgrimmar.", tgo={{"Íncubo invocado"}}},
    [65610] = {n="Ojalá estuvieras aquí", d="Investiga el Lago Cielo Estrellado de Vallefresno e informa de tus hallazgos a Gan'rul Ojosangre, que está en Orgrimmar.", tgo={{"Muevepiedras Sombramatorral", "Desgarracortezas Sombramatorral", "Oráculo Sombramatorral"}}},
    [78261] = {n="El Cuerno de Xelthos", d="Encuentra el Cuerno de Xelthos dentro del Castillo de Colmillo Oscuro. Después llévalo al escondite secreto de C cerca de la Aldea Piroleña. Debes hacerlo en solitario."},
