    [91497] = {n="Seals of the Sin'dorei", d="Botín de: Lieutenant Suncrest, Magistrix Yelmalcón, Ranger Lydrea", tgo={{"Lieutenant Suncrest"}, {"Magistrix Yelmalcón"}, {"Ranger Lydrea"}}},
