    [97253] = {n="Volver con piezas de una pieza", d="Consigue 5 puñados de piezas complicadas del campamento pirata superior que hay al sur de Trinquete y luego vuelve con Desdio el Desdichado en Trinquete.", objs={"Montón de piezas complicadas"}},
    [97257] = {n="La llamada del fuego", d="Espera a que Olariaan empiece el ritual en el blandón de ofrendas y sigue sus instrucciones.\nDebes entregar la Llama eterna en Valanaar antes de que se agote el tiempo.", tgo={{"Blandón de ofrendas"}, {"Blandón de la Llama eterna"}}, star={"Tótem de las llamas cargadas", {"SHAMAN"}}},
    [97265] = {n="Odio al Odio Feroz", d="Derrota a sátiros Odio Feroz en Sargeron, Desolace, y luego vuelve con Aka'rai en la Aldea Cazasombras.", tgo={{"Tramposo Odio Feroz"}, {"Clamainferno Odio Feroz"}, {"Acechasombras Odio Feroz"}, {"Jurapenas Odio Feroz"}, {"Pícaro Odio Feroz"}}},
    [97279] = {n="Armas extraviadas", d="Recoge 6 armas de entrenamiento abandonadas y llévaselas a Kzan Trallafusta en El Cubil.", objs={"Arma de entrenamiento abandonada"}},
    [97281] = {n="Una tormenta inminente", d="Llévale el orbe de tormenta sin brillo a Rezlak, cerca del Barranco Árido."},
    [97282] = {n="Potencial tormentoso", d="Llévale 5 órganos de truenagarto cargados a Rezlak, cerca del Barranco Árido.", tgo={{"Truenagarto", "Lomorrayo", "Halikor"}}},
    [97287] = {n="Negociaciones astutas", d="Habla con la imagen de la archimaga Modera cerca de Dalaran."},
    [97288] = {n="Tormento interminable", d="Entrega la cabeza abominable al maestro boticario Faranell en Entrañas."},
    [97289] = {n="Tormento interminable", d="Lleva la cabeza del barón junto al cuerpo de Othmar en Entrañas."},
    [97290] = {n="Tormento interminable", d="Informa de tus hallazgos al maestro boticario Faranell de Entrañas."},
    [97291] = {n="Tormento interminable", d="Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a los instructores de herboristería para reunir hierba ampolla y a la vendedora de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.", objs={"Hierba ampolla"}},
    [97292] = {n="Tormento interminable", d="Inyecta el suero siseante en el sistema que hay sobre el cuerpo de Othmar para el maestro boticario Faranell.", objs={"Othmar's Head"}},
    [97327] = {n="Blackmaw Pouches", d="Botín de: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", tgo={{"Blackmaw Berserker", "Blackmaw Thrall", "Blackmaw Headhunter"}}},
    [97328] = {n="Cualquier objeto de valor", d="Recupera 8 envíos robados de las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévaselos a alguien en Bahía del Botín."},
    [97329] = {n="¿Dónde está la llave?", d="Consigue la llave primitiva de los trols en las Ruinas de Zul'Kunda, en la Vega de Tuercespina, y llévasela a Zimmix Escupechispa.", tgo={{"Explorador Cabellesangre", "Cazador Cabellesangre", "Rabioso Cabellesangre"}}},
    [97331] = {n="La gran evasión de Zimmix", d="Escolta a Zimmix Escupechispa fuera de las Ruinas de Zul'Kunda e informa al jefe de embarcadero Lozgil del éxito de tu rescate en Bahía del Botín."},
    [97332] = {n="Tropezar dos veces con la misma piedra", d="Entrega el paquete pedido dos veces al maestro de los muelles Silbazumbido en Puerto Polvofusil, en Clarofluvial."},
    [97386] = {n="La ofensa de Grom'gol", d="El comandante del Campamento Grom'gol, Aggro'gosh, quiere que mates ogros en el Túmulo Ogro Mosh'Ogg.", tgo={{"Creaconjuros Mosh'Ogg"}, {"Belicista Mosh'Ogg"}, {"Destructor Mosh'Ogg"}, {"Chamán Mosh'Ogg"}}},
    [97453] = {n="Mala hierba segada", d="Mata 6 hierbas carnívoras al sur de Grom'gol e informa a la madre de Gemmil.", tgo={{"Hierba carnívora"}}},
    [97485] = {n="Tradiciones de la cima", d="Compra un fardo de hierbas a Nida la herborista, un fardo de ramas de cedro a Nata la proveedora de encantamientos, hilo tendinoso a Mahu el proveedor de suministros de peletería, y sílex y yesca ceremoniales a Naal el proveedor de artículos de cocina.\nCombina los objetos y esparce el incienso desde el Alto de los Cazadores.", objs={"Quemador de incienso"}},
    [97530] = {n="Machacadunas deudores", d="El jefe de seguridad Pasaquillas del Puerto Bonvapor, en Tanaris, te pide que recuperes un brazalete brillante que se extravió cerca del hábitat de los ogros Machacadunas.", tgo={{"Ogro Machacaduna", "Déspota Machacaduna", "Magro ogro Machacaduna"}}},
    [97534] = {n="Las arenas del trapicheo", d="Quinn quiere que consigas 7 unidades de escombros del desierto y se las lleves a Gadgetzan."},
    [97539] = {n="Suturas sedosas", d="Entrega 12 sedas de araña quirúrgicas al doctor Gregory Victor en Sentencia, en las Tierras Altas de Arathi.", tgo={{"Trepador de las llanuras", "Trepador de las llanuras gigante"}}},
    [97558] = {n="Pieles para los Renegados", d="Lleva 8 membranas de ala de murciumbrío, 6 pellejos de can oscuro y 3 piel de múrloc Anca Vil a Shelene Rhobart.", tgo={{"Murciumbrío superior", "Murciumbrío vampírico"}, {"Can oscuro decrépito", "Can oscuro maldito"}, {"Oráculo menor Anca Vil", "Habitabosta Anca Vil"}}},
    [97908] = {n="Acampada para novatos: desuello", d="Habla con Thuwd en Orgrimmar para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad.", tgo={{"Thuwd"}}},
    [97936] = {n="Acampada para novatos: desuello", d="Habla con Yonn Corte Profundo en el Poblado Pezuña de Sangre para aprender a crear un objeto de acampada para tu profesión cuando hayas demostrado tu destreza en la habilidad.", tgo={{"Yonn Corte Profundo"}}},
    [98024] = {n="Viaje a El Cruce", d="Preséntate ante Thork en El Cruce de Los Baldíos."},
    [98069] = {n="Los suministros de Viento Libre robados", d="Llévale 8 suministros de Viento Libre robados a Jandia en el Poblado Viento Libre."},
    [98070] = {n="Silenciar el chirrido", d="Mata a 5 arpías estridentes, 5 arpías Malapluma estridentes y 5 arpías clamavientos estridentes.", tgo={{"Arpía estridente"}, {"Malapluma estridente"}, {"Clamavientos estridente"}}},
    [98093] = {n="Un campo que despejar", d="Sulhasa, en Los Baldíos del Sur, quiere que elimines a 7 lagartos tormenteros y a 7 acechadores Dentecenado en la zona para que pueda bajar del árbol sin peligro.", tgo={{"Acechador Dentecenado"}, {"Tormentero"}}},
    [98094] = {n="Asistencia a los exploradores", d="La suma ejecutora Darthalia quiere que le entregues las nuevas órdenes al mortacechador Masoj, que se encuentra al sur de Molino Tarren, justo a las afueras de Dun Garok."},
    [98095] = {n="Ventajas valiosas", d="El mortacechador Masoj necesita que coloques tres viales de apotecarios en los lugares claves de las Laderas de Trabalomas. Después, regresa con él."},
    [98298] = {n="La locura de Arugal", d="Llévale 6 tapitas de huargen a Dalar Tejealba en El Sepulcro.", tgo={{"Aullasangre Furia Lunar"}}},
    [98299] = {n="Detener la propagación", d="Mata a 5 refugiados enfermos y a 5 refugiados demacrados para Dalar Tejealba en El Sepulcro.", tgo={{"Refugiado Haggard"}, {"Refugiado enfermo"}}},
    [98340] = {n="El gran espíritu felino", d="Habla con Dendrita Rafagaestelar en el poblado Amparo de la Noche, en Claro de la Luna."},
    [98341] = {n="El espíritu del gran felino natoviento", d="Busca al avatar de Saeyleenan al sur de Claro de la Luna y descubre lo que tiene que mostrarte sobre la naturaleza del felino natoviento."},
    [98342] = {n="El gran espíritu felino", d="Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa en el Túmulo de Tempestira. Después, entrégaselas al gran espíritu felino.", objs={"Reliquia del colmillo", "Reliquia de la garra", "Reliquia de la sombra silenciosa"}},
    [98362] = {n="Viaje a Cima del Trueno", d="Vuelve a Cima del Trueno para hablar con Turak Tótem Rúnico en Alto de los Ancestros."},
    [98389] = {n="Una luz en la oscuridad", d="Libera a 6 víctimas enredadas en la Hoya Nocturácnidas para Aramis Manomartillo en Camposanto."},
    [98404] = {n="El espíritu del gran felino natoviento", d="Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa en el Túmulo de Tempestira. Después, entrégaselas al avatar de Saeyleenan.", objs={"Reliquia del colmillo", "Reliquia de la garra", "Reliquia de la sombra silenciosa"}},
    [98405] = {n="El gran espíritu felino", d="Busca al gran espíritu felino al sur de Claro de la Luna y descubre lo que tiene que mostrarte sobre la naturaleza del felino."},
    [98424] = {n="Las notas de Saltatuercas", d="Reúne el resto de las páginas del supervisor Saltatuercas dentro de la Mina Ventura y Cía. y llévaselas a Morin Acechanubes cerca del Poblado Pezuña de Sangre.", objs={"Instrucciones de manejo de trituradora", "Manual de buenas prácticas de las operaciones en Los Baldíos", "Un tal Gerenzo de Sierra Espolón"}},
    [98427] = {n="Cese de operaciones", d="Llévale la llave de cortador a Morin Acechanubes, a las afueras del Poblado Pezuña de Sangre.", tgo={{"Desbrozadora de Ventura y Cía."}}},
    [98430] = {n="Los caminantes", d="Ayuda a Perith Pezuña Tempestuosa a escapar de Roca Crines Pálidas e informa de su bienestar a Cairne Pezuña de Sangre, en Cima del Trueno."},
    [98435] = {n="Informe de Astatrueno", d="Llévale el informe de Astatrueno al archidruida Hamuul Runatótem en Cima del Trueno."},
    [98575] = {n="Tainted Tablet", d="Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials."},
    [98576] = {n="Glyphic Parchment", d="Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
    [98601] = {n="Una senda complicada", d="Lee el pergamino consagrado y luego ve a la iglesia de Camposanto y habla con Aramis Manomartillo."},
    [98738] = {n="Bendiciones del gran espíritu felino natoviento", d="Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrite Rafagaestelar a Amparo de la Noche."},
    [98739] = {n="Bendiciones del gran espíritu felino", d="Habla con Dendrita."},
    [98823] = {n="Eco terráneo", d="Entrega la reliquia titánica a Muln Furiatierra, que está en la Meseta de Miracielos de Mulgore."},
    [99048] = {n="La Mano desaparecida", d="Busca a Heglan Ojoumbrío al norte del Fuerte de Tiragarde."},
    [99049] = {n="La amenaza de las profundidades", d="Busca indicios de lo que ha atacado a Heglan Ojoumbrío.", objs={"Daga abandonada", "Escombros extraños", "Pieza de arma"}},
    [99051] = {n="La amenaza de las profundidades", d="Consigue 9 aletas espinosas de naga.", tgo={{"Explorador Látigo de Ira", "Ayudante Látigo de Ira"}}},
    [99052] = {n="La amenaza de las profundidades", d="Mata al gigante de mar en la costa norte de Durotar y vuelve con alguna prueba de tu hazaña.", tgo={{"Aggor el Joven"}}},
    [99079] = {n="Caminante Malah", d="Encuentra a la caminante Malah Ventolongo al este del Poblado Pezuña de Sangre, cerca del límite de Mulgore."},
    [99080] = {n="Hay que expulsarlos", d="Mata a 6 centauros Galak y 4 avanzados Galak, y llévale la cabeza de Herak el Saqueador a Baine Pezuña de Sangre.", tgo={{"Centauro Galak"}, {"Avanzado Galak"}, {"Herak el Saqueador"}}},
    [99081] = {n="Noticias aciagas", d="Llévale el informe de la caminante Malah a Valiente Corresalvaje en el Poblado Pezuña de Sangre."},
    [99082] = {n="El Gran jefe", d="Solicita audiencia con el Gran jefe Cairne Pezuña de Sangre en Cima del Trueno."},
    [99101] = {n="Nuestro viejo enemigo", d="Llévale el informe de la caminante Malah a Baine Pezuña de Sangre."},
    [99108] = {n="Combate de práctica", d="Derrota a 3 jugadores o guerreros novicios en duelos para Tang Pezuñapétrea.", tgo={{"Guerrero novicio"}}},
    [99123] = {n="Perdida en las sombras", d="Ayuda a Pal'juh a escapar del Risco Kolkar y llévale noticias de tu hazaña al maestro Vornal en el Poblado Sen'jin."},
    [99134] = {n="Disciplina", d="Castiga a 5 guardias de la muerte para el ejecutor Zygand."},
    [99141] = {n="Paciencia", d="Consigue los informes del guardia de la Muerte Dillinger, el guardia de la Muerte Kristof y Gordo para el ejecutor Zygand.", tgo={{"Guardia de la Muerte Dillinger"}, {"Guardia de la Muerte Kristof"}, {"Gordo"}}},
    [99142] = {n="Tumbalíseas", d="Recoge 5 tumbalíseas y entrégaselas al boticario de segunda Holland.", objs={"Tumbalíseas"}},
    [99156] = {n="Patrulla de la retaguardia", d="Llévale el corazón de Rasgallanto a la guardia de la Muerte Linnea.", tgo={{"Rasgallanto"}}},
    [99187] = {n="The Reliquary of Tyr", d="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", star={"Sword of Mourning", {"PALADIN"}}},
    [99411] = {n="¡Kyle ha desaparecido!", d="Ahab Pezuña de Trigo del Poblado Pezuña de Sangre, en Mulgore, quiere que des de comer a su apreciado cachorro, Kyle el Demenciado.\nDale a Kyle carne de zancudo tierna y vuelve junto a Ahab Pezuñatrigo.", tgo={{"Kyle el Demenciado"}}},
